import java.util.*;
import java.io.*;

public class Main {
    static int[] countFaster(int[] parent, int[] t) {
        // parent[0] = -1 (the CEO); parent[i] is the manager of employee i
        // Write your solution here
        return new int[t.length];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[] parent = new int[n];
        parent[0] = -1;
        for (int i = 1; i < n; i++) {
            in.nextToken();
            parent[i] = (int) in.nval;
        }
        int[] t = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            t[i] = (int) in.nval;
        }
        int[] ans = countFaster(parent, t);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(ans[i]).append(i + 1 < n ? " " : "\n");
        System.out.print(sb);
    }
}

