def gen(rng):
    def build(n, maxdepth, mode):
        par = [-1] * n
        depth = [0] * n
        for i in range(1, n):
            if mode == 'chain':
                p = i - 1
                if depth[p] >= maxdepth:
                    p = rng.randint(0, i - 1)
                    while depth[p] >= maxdepth:
                        p = rng.randint(0, i - 1)
            elif mode == 'star':
                p = 0
            else:
                p = rng.randint(0, i - 1)
                while depth[p] >= maxdepth:
                    p = rng.randint(0, i - 1)
            par[i] = p
            depth[i] = depth[p] + 1
        perm = list(range(1, n))
        rng.shuffle(perm)
        perm = [0] + perm
        newpar = [-1] * n
        for i in range(1, n):
            newpar[perm[i]] = perm[par[i]]
        return newpar
    def fmt(par, t):
        n = len(t)
        return f'{n}\n' + ' '.join(map(str, par[1:])) + '\n' + ' '.join(map(str, t))
    tests = [fmt([-1], [5]), fmt([-1, 0], [1, 2]), fmt([-1, 0], [2, 1]), fmt([-1, 0, 0, 1, 1], [5, 3, 8, 4, 9]),
             fmt([-1, 0, 1, 2], [3, 1, 4, 2]), fmt([-1, 0, 0], [5, 5, 5]), fmt([-1, 0, 1, 2, 3], [5, 4, 3, 2, 1]),
             fmt([-1, 0, 1, 2, 3], [1, 2, 3, 4, 5])]
    for n in (3, 5, 8, 12, 20, 30):
        for mode in ('rand', 'chain', 'star'):
            par = build(n, 10**9, mode)
            hi = rng.choice([3, 10, 10**9])
            tests.append(fmt(par, [rng.randint(1, hi) for _ in range(n)]))
    N = 100000
    for mode, hi in (('rand', 10**9), ('chain', 10**9), ('rand', 5), ('star', 10**9)):
        par = build(N, 4900, mode)
        tests.append(fmt(par, [rng.randint(1, hi) for _ in range(N)]))
    par = build(N, 4900, 'chain')
    tests.append(fmt(par, list(range(N, 0, -1))))
    return tests
